-- One-shot data fixture for sources.public_description. Re-runnable.
-- Each description is curator's voice, ~40-60 words, focused on what the
-- publication actually does + why a reader would want it on their feed.

update sources set public_description = $$Daily roundup of essays in philosophy, science, politics, and culture. Long-running, contributor-driven; a thinking person's daily browse.$$ where slug = '3quarks';

update sources set public_description = $$Outdoor writing without the gear-review fluff. Reporting and essays on climbing, surfing, conservation, and the lives that orbit them.$$ where slug = 'adventure-journal';

update sources set public_description = $$Long essays in philosophy, psychology, science, and culture. Single-author, deeply argued — the kind of piece you save and finish on the train home.$$ where slug = 'aeon';

update sources set public_description = $$Cultural criticism, politics, and reportage from across the African continent and its diaspora. Sharp, often confrontational, consistently the smartest English-language writing on the region.$$ where slug = 'africa-is-a-country';

update sources set public_description = $$Alpine climbing as literature. Long features on mountain culture, first ascents, and the people who keep going up. Print-first, so the web archive runs a few months behind.$$ where slug = 'alpinist';

update sources set public_description = $$The Phi Beta Kappa Society's quarterly. Humanities essays, criticism, and memoir, often by working scholars writing for general readers.$$ where slug = 'american-scholar';

update sources set public_description = $$General-interest reporting and essays with a long house style. Politics, science, books, ideas. The best pieces shape conversations; a metered paywall lets you in for a few each month.$$ where slug = 'atlantic';

update sources set public_description = $$Reporting on the obscure corners of the world: hidden places, lost histories, strange foods, forgotten people. Genuinely curious, never glib.$$ where slug = 'atlas-obscura';

update sources set public_description = $$Independent blog on energy, manufacturing, and how physical systems actually work. First-principles explainers, deeply technical, no padding.$$ where slug = 'austin-vernon';

update sources set public_description = $$Cultural criticism with the knives out. Sharp, often funny, occasionally maddening — the antidote to thinkpiece complacency.$$ where slug = 'baffler';

update sources set public_description = $$The California Academy of Sciences' nature magazine. Reporting on biodiversity and conservation, told through individual species and ecosystems. Beautifully photographed.$$ where slug = 'biographic';

update sources set public_description = $$Politics, literature, and ideas from the Cambridge intellectual tradition. Forum-style: a lead essay plus responses, then a final word.$$ where slug = 'boston-review';

update sources set public_description = $$Left politics with a long view. Founded in 1954, still publishing, still arguing. Theory, criticism, organizing — not news.$$ where slug = 'dissent';

update sources set public_description = $$Ecology, myth, and place. Slow, gorgeously produced essays on humans-in-the-world. The opposite of a news feed.$$ where slug = 'emergence';

update sources set public_description = $$Literary magazine of new writing. Memoir, fiction, international dispatches; the issues hold up well years after publication.$$ where slug = 'granta';

update sources set public_description = $$Climate journalism with reporting muscle. Policy, technology, environmental justice — sober without being grim.$$ where slug = 'grist';

update sources set public_description = $$Literary politics. Essays, interviews, poetry, and fiction from a writer-centered editorial. Bylines often outpace the bigger magazines a year later.$$ where slug = 'guernica';

update sources set public_description = $$Coastal science and culture. Marine ecology, fisheries, coastal communities. Nonprofit, well-edited, narrowly focused — and the better for it.$$ where slug = 'hakai';

update sources set public_description = $$One of the oldest American magazines, still essay-first. Politics, the arts, and a back-of-book of fragments. Metered paywall; a library card usually gets you in.$$ where slug = 'harpers';

update sources set public_description = $$Academic humanities translated for public readers. Each piece anchored to a peer-reviewed paper you can read for free through JSTOR.$$ where slug = 'jstor-daily';

update sources set public_description = $$Themed quarterly issues built from primary sources. Each issue is one topic — war, money, friendship — explored through ancient and modern voices side by side.$$ where slug = 'laphams';

update sources set public_description = $$Climate-tech and clean-energy reporting. Pragmatic, project-level, very few thinkpieces. Where the people actually building the transition read.$$ where slug = 'latitude-media';

update sources set public_description = $$Literary news, essays, and book criticism. High-volume, mixed signal, but the essay output is consistently strong.$$ where slug = 'lithub';

update sources set public_description = $$Editor-curated list of the best longform on the web each week, plus original commissions. The original aggregator and still useful.$$ where slug = 'longreads';

update sources set public_description = $$Nature, culture, and science reporting backed by world-class photography. Features more than news. Metered paywall.$$ where slug = 'nat-geo';

update sources set public_description = $$Science writing as literature. Single-topic issues, single-author features, deeply researched. Read for the reasoning, not the headlines.$$ where slug = 'nautilus';

update sources set public_description = $$Theory, criticism, internet-shaped politics. Edgy, very online, sometimes brilliant — always trying something.$$ where slug = 'new-inquiry';

update sources set public_description = $$American magazine writing at its longest and most reported. Profiles, criticism, fiction, dispatches. Metered paywall; the magazine features are the reason to come.$$ where slug = 'new-yorker';

update sources set public_description = $$Literary criticism and political theory from a Brooklyn editorial. Long, often combative essays; the founding generation of millennial editors.$$ where slug = 'nplusone';

update sources set public_description = $$Adventure journalism that occasionally rises above gear-and-trip. The long features — survival narratives, environmental reporting, profiles — are what we filter for.$$ where slug = 'outside';

update sources set public_description = $$Fiction, poetry, and the Art of Interview series — long-form conversations with novelists, poets, and playwrights that often read better than most criticism.$$ where slug = 'paris-review';

update sources set public_description = $$Y Combinator co-founder, essayist on startups, writing, and thinking. Plain HTML, no images, no ads — just argument.$$ where slug = 'paul-graham';

update sources set public_description = $$Investigative journalism, in the public interest, freely republishable. Long-form accountability reporting on what institutions don't want you to know.$$ where slug = 'propublica';

update sources set public_description = $$Academic criticism for the curious reader. Reviews of new books and arguments across the humanities and social sciences.$$ where slug = 'public-books';

update sources set public_description = $$Historical curios, illustrated archives, and essays on what's slipped out of copyright. Reads like a Victorian magazine should.$$ where slug = 'public-domain-review';

update sources set public_description = $$Reddit community curating long features from across the web. Voting-driven, surfaces things the regular feeds miss.$$ where slug = 'reddit-longform';

update sources set public_description = $$Travel and food writing that takes both seriously. Dispatch journalism from places major magazines don't reach.$$ where slug = 'roads-and-kingdoms';

update sources set public_description = $$Literary essays, advice columns, and conversations. Personal-essay heavy; sometimes uneven, often unexpectedly good.$$ where slug = 'rumpus';

update sources set public_description = $$Public anthropology. Field reports, conceptual essays, and profiles of cultures and the researchers studying them.$$ where slug = 'sapiens';

update sources set public_description = $$Adventure photography and reportage from remote landscapes. Print magazine; web archive curated from features.$$ where slug = 'sidetracked';

update sources set public_description = $$Weekly newsletter rounding up the best longform from across the web. Functions as an editorial filter on top of everyone else's output.$$ where slug = 'sunday-long-read';

update sources set public_description = $$Academic explainers written by working researchers for general audiences. Topical news angles, but the depth comes from the writer's actual expertise.$$ where slug = 'the-conversation';

update sources set public_description = $$International longform, founded in 2022. Writers based outside their countries of origin, plus translation. Covers what Western magazines miss.$$ where slug = 'the-dial';

update sources set public_description = $$Fly fishing prose and photography. Better than it sounds — the writing borrows from outdoor literature traditions and rarely talks about equipment.$$ where slug = 'the-drake';

update sources set public_description = $$Philosophy and criticism for non-philosophers. Long essays on everyday life, art, and politics, often using continental theory without showing off.$$ where slug = 'the-point';

update sources set public_description = $$Technology reporting and longer feature work. Metered paywall; the features are uneven, but the best are excellent.$$ where slug = 'wired';
